mapper.select:
SELECT id, name, location, resource_type, unit_label, enabled
FROM resource
WHERE id = #{id}

SELECT id, resource_id, start_at, end_at
FROM resource_opening
WHERE resource_id = #{resourceId}
  AND start_at <= #{start}
  AND end_at >= #{end}
ORDER BY start_at
LIMIT 1

SELECT id, resource_id, start_at, end_at
FROM resource_opening
WHERE resource_id = #{resourceId}
  AND start_at <= #{start}
  AND end_at >= #{end}
ORDER BY start_at
LIMIT 1
FOR UPDATE

SELECT id,resource_id,start_at,end_at FROM resource_opening
WHERE resource_id=#{resourceId} AND start_at < #{end} AND end_at > #{start}
ORDER BY start_at,id FOR UPDATE

SELECT id, resource_id, start_at, end_at
FROM resource_opening
WHERE resource_id = #{resourceId}
  AND start_at < #{dayEnd}
  AND end_at > #{dayStart}
ORDER BY start_at

SELECT id, resource_id, block_type, start_at, end_at, reason
FROM resource_block
WHERE resource_id = #{resourceId}
  AND start_at < #{dayEnd}
  AND end_at > #{dayStart}
ORDER BY start_at

SELECT id, start_at, end_at, status
FROM reservation
WHERE resource_id = #{resourceId}
  AND status IN ('RESERVED', 'CHECKED_IN')
  AND start_at < #{dayEnd}
  AND end_at > #{dayStart}
ORDER BY start_at
